import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { describe, expect, it } from "vitest";
import { verifyRetainedHead } from "../src/retained-head.js";

// verifyRetainedHead against vectors/checkpoint-consistency (generated by
// python/scripts/generate_checkpoint_consistency_vectors.py).
const DIR = resolve(process.cwd(), "..", "vectors", "checkpoint-consistency");

type Case = {
  id: string;
  retained: unknown;
  current: unknown;
  proof?: unknown;
  expect: { status: string; finding: string | null };
};
const vectors = JSON.parse(
  readFileSync(resolve(DIR, "vectors.json"), "utf8"),
) as { cases: Case[] };
const manifest = JSON.parse(
  readFileSync(resolve(DIR, "manifest.json"), "utf8"),
) as { case_count: number };

describe("retained-head vectors", () => {
  it("runs every case the manifest counts", () => {
    expect(vectors.cases).toHaveLength(manifest.case_count);
  });

  it("covers every status", () => {
    const statuses = new Set(vectors.cases.map((c) => c.expect.status));
    expect([...statuses].sort()).toEqual(["fail", "not_present", "pass"]);
  });

  it.each(vectors.cases.map((c) => [c.id, c] as const))(
    "%s",
    async (_id, testCase) => {
      const result = await verifyRetainedHead(
        testCase.retained,
        testCase.current,
        testCase.proof,
      );
      expect(result).toEqual(testCase.expect);
    },
  );
});
